    [('400', 'jinja_env 编译缓存的默认容量'), (f'{fl_[0] / fl_[1]:.0f}×', '第一次请求(含编译)相对之后请求的耗时倍数'), (f'{au["True"] / au["False"]:.1f}×', 'auto_reload=True 相对 False 的缓存命中耗时')],
    [('缓存命中', '<p>上一篇:<a href="flask-template-render-exception.html">模板渲染异常处理</a>;下一篇:<a href="flask-jinja2-bytecode-cache.html">Jinja2 Bytecode Cache</a>。编译与渲染的耗时见<a href="flask-jinja2-template-loader.html">Jinja2 Template Loader</a>。</p>'), ('auto_reload 的代价', None), ('改文件后', None), ('缓存容量', None), ('关闭与清空缓存', None), ('Flask 的配置', None), ('第一次请求', None)],
